// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(this));
    }

    function _test(address sender, uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > c.MinDeposit());
        sender = address(this);
        vm.assume(address(this).balance >= amt);
        uint256 beforeBal;
        try c.balances(sender) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        try c.Deposit{value: amt}() {} catch { return; }
        uint256 afterBal;
        try c.balances(sender) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == beforeBal + amt);
    }

    function testFuzz_test(address sender, uint256 amt) public {
        _test(sender, amt);
    }

    receive() external payable {}

    fallback() external payable {}
}
